download_cds_requests <- function(requests, raw_dir, run_dir, dry_run=TRUE, overwrite=FALSE, workers=1) { fs::dir_create(raw_dir,recurse=TRUE); statuses <- lapply(requests,function(req) { validate_cds_request_structure(req); target <- file.path(raw_dir,req$target); if(file.exists(target)&&file.info(target)$size>0&&!overwrite) return(data.frame(target=target,status="skipped_existing",error="",stringsAsFactors=FALSE)); if(dry_run) return(data.frame(target=target,status="planned",error="",stringsAsFactors=FALSE)); if(!requireNamespace("ecmwfr",quietly=TRUE)) stop("Package 'ecmwfr' is required for downloads"); if(!nzchar(Sys.getenv("ecmwfr_PAT", ""))) stop("ecmwfr_PAT is not set; configure CDS credentials before downloading"); tmp <- paste0(target,".part"); ans <- tryCatch(do.call(ecmwfr::wf_request,list(request=req,transfer=TRUE,path=dirname(tmp))), error=function(e)e); if(inherits(ans,"error")) data.frame(target=target,status="failed",error=conditionMessage(ans),stringsAsFactors=FALSE) else { if(file.exists(tmp)) fs::file_move(tmp,target); data.frame(target=target,status="downloaded",error="",stringsAsFactors=FALSE) } }); out <- if(length(statuses)) do.call(rbind,statuses) else data.frame(); if(!is.null(run_dir)) utils::write.csv(out,file.path(run_dir,"download_manifest.csv"),row.names=FALSE); out }
